alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend(p_user_id uuid, p_friend_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.friendships f
    where ((f.requester_id = p_user_id and f.addressee_id = p_friend_id)
          or (f.requester_id = p_friend_id and f.addressee_id = p_user_id))
      and f.status = 'accepted'
  );
$$;

create or replace function public.enforce_friendship_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.requester_id is distinct from old.requester_id
     or new.addressee_id is distinct from old.addressee_id then
    raise exception 'friendship endpoints cannot be changed';
  end if;

  if old.status = 'accepted' then
    raise exception 'only pending friendships can be updated';
  end if;

  if new.status <> 'pending' and new.status <> 'accepted' then
    raise exception 'invalid friendship status';
  end if;

  if old.status = 'pending' then
    if auth.uid() is distinct from old.addressee_id then
      raise exception 'only the addressee can accept a friend request';
    end if;
    if new.status = 'accepted' then
      if old.requester_id = auth.uid() then
        raise exception 'cannot accept your own friend request';
      end if;
    else
      if old.requester_id = auth.uid() then
        raise exception 'requesters cannot update their own pending requests';
      end if;
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_friendship_update_trigger
before update on public.friendships
for each row execute function public.enforce_friendship_update();

create policy friendships_select_own_or_participant
on public.friendships for select to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy friendships_insert_own_request
on public.friendships for insert to authenticated
with check (requester_id = auth.uid() and status = 'pending');

create policy friendships_update_addressee_accept
on public.friendships for update to authenticated
using (status = 'pending' and addressee_id = auth.uid())
with check (status = 'accepted');

create policy friendships_delete_participant
on public.friendships for delete to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy posts_select_by_audience
on public.posts for select to anon, authenticated
using (
  audience = 'public'
  or (auth.uid() is not null and (author_id = auth.uid() or public.is_friend(auth.uid(), author_id)))
);

create policy posts_insert_own
on public.posts for insert to authenticated
with check (author_id = auth.uid());

create policy posts_update_own
on public.posts for update to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy posts_delete_own
on public.posts for delete to authenticated
using (author_id = auth.uid());
