alter table public.auctions enable row level security;
alter table public.bids enable row level security;

revoke all on table public.auctions from public;
revoke all on table public.bids from public;
revoke all on sequence public.bids_id_seq from public;

grant select on table public.auctions to authenticated;
grant select on table public.bids to authenticated;
grant usage on sequence public.bids_id_seq to authenticated;

create policy "auctions_select_authenticated"
on public.auctions for select to authenticated
using (true);

create policy "bids_select_own_or_seller"
on public.bids for select to authenticated
using (bidder_id = (select auth.uid())
        or exists (select 1 from public.auctions a where a.id = bids.auction_id and a.seller_id = (select auth.uid())));

create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest_bid numeric;
  v_min_increment numeric;
begin
  if v_caller is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at < now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = v_caller then
    raise exception 'cannot bid on own auction';
  end if;

  v_min_increment := v_auction.min_increment;
  if v_auction.highest_bid is null then
    v_current_highest_bid := v_auction.starting_price;
  else
    v_current_highest_bid := v_auction.highest_bid;
  end if;

  if p_amount < v_current_highest_bid + v_min_increment then
    if v_auction.highest_bid is null and p_amount < v_auction.starting_price then
      raise exception 'bid must meet starting price';
    else
      raise exception 'bid too low';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_caller, p_amount);

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_caller
  where id = p_auction_id;

  return p_amount;
end;
$$;

revoke all on function public.place_bid(bigint, numeric) from public;
grant execute on function public.place_bid(bigint, numeric) to authenticated;
```

