```sql
alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

create or replace function public.class_capacity(p_class_id bigint)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select c.capacity from public.classes c where c.id = p_class_id;
$$;

create or replace function public.class_enrolled_count(p_class_id bigint)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer from public.class_spots s where s.class_id = p_class_id and s.status = 'enrolled';
$$;

create or replace function public.is_class_instructor(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.classes c where c.id = p_class_id and c.instructor_id = auth.uid());
$$;

create or replace function public.prevent_class_schema_change()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.id is distinct from (select c.id from public.classes c where c.title = new.title) then
      raise exception 'class id cannot be changed';
    end if;
    if new.instructor_id is distinct from auth.uid() then
      raise exception 'instructor id cannot be changed by this user';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id then
      raise exception 'class id cannot be changed';
    end if;
    if new.instructor_id is distinct from old.instructor_id then
      raise exception 'instructor id cannot be changed';
    end if;
    if new.capacity is distinct from old.capacity then
      raise exception 'class capacity cannot be changed';
    end if;
  end if;
  return new;
end;
$$;

create trigger prevent_class_schema_change_trigger
before insert or update on public.classes
for each row execute function public.prevent_class_schema_change();

create policy classes_select_authenticated
on public.classes for select to authenticated
using (true);

create policy class_spots_select_own_or_instructor
on public.class_spots for select to authenticated
using (user_id = auth.uid() or public.is_class_instructor(class_id));

create policy class_spots_insert_own
on public.class_spots for insert to authenticated
with check (
  user_id = auth.uid()
  and status in ('enrolled', 'waitlisted')
  and (
    status = 'enrolled'
    and public.class_enrolled_count(class_id) < public.class_capacity(class_id)
    or status = 'waitlisted'
    and public.class_enrolled_count(class_id) >= public.class_capacity(class_id)
  )
);

create policy class_spots_update_own_waitlisted
on public.class_spots for update to authenticated
using (user_id = auth.uid() and status = 'waitlisted')
with check (user_id = auth.uid() and status = 'enrolled' and public.class_enrolled_count(class_id) < public.class_capacity(class_id));

create policy class_spots_delete_own
on public.class_spots for delete to authenticated
using (user_id = auth.uid());

create policy class_spots_delete_instructor
on public.class_spots for delete to authenticated
using (public.is_class_instructor(class_id));
